ValidationRule.errorConditionFormula:
OR 
( 
ISNEW() && (

NOT(BEGINS(  Name , UPPER(LEFT( Name , 1) )))

/*IF( Case_Accounts__c == False,IF( NOT(RecordTypeId == '0127F000000mhAV') && NOT(RecordTypeId == '0127F000000mhAT'), NOT(BEGINS(Name , UPPER(LEFT( Name , 1) ))), FALSE), false) */

)
, 
DATEVALUE(CreatedDate)>=DATEVALUE("2018-07-01") && 
( 

NOT(BEGINS(  Name , UPPER(LEFT( Name , 1) )))

/*IF( Case_Accounts__c == False,IF( NOT(RecordTypeId == '0127F000000mhAV') && NOT(RecordTypeId == '0127F000000mhAT'), NOT(BEGINS(Name , UPPER(LEFT( Name , 1) ))), FALSE), false) */

)
)
